import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AdminSidebar from '../../components/AdminSidebar';
import toast from 'react-hot-toast';

const AdminUsersPage = () => {
  const { user, api } = useAuth();
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showVerifyModal, setShowVerifyModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [adminNotes, setAdminNotes] = useState('');

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }
    fetchUsers();
  }, [user, navigate]);

  const fetchUsers = async () => {
    try {
      const response = await api.get('/admin/users');
      setUsers(response.data);
    } catch (error) {
      console.error('Error fetching users:', error);
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (approved) => {
    if (!selectedUser) return;

    try {
      const status = approved ? 'approved' : 'rejected';
      await api.put(`/admin/users/${selectedUser._id}/verify`, {
        isVerified: approved,
        verificationStatus: status,
        verificationNotes: adminNotes
      });

      toast.success(approved ? 'User verified successfully!' : 'User rejected');
      fetchUsers();
      setShowVerifyModal(false);
      setSelectedUser(null);
      setAdminNotes('');
    } catch (error) {
      toast.error('Failed to verify user');
    }
  };

  const handleSuspend = async (userId, currentStatus) => {
    if (window.confirm(`Are you sure you want to ${currentStatus ? 'unsuspend' : 'suspend'} this user?`)) {
      try {
        await api.put(`/admin/users/${userId}/suspend`);
        toast.success(`User ${currentStatus ? 'unsuspended' : 'suspended'} successfully`);
        fetchUsers();
      } catch (error) {
        toast.error('Operation failed');
      }
    }
  };

  const openVerifyModal = (userData) => {
    setSelectedUser(userData);
    setAdminNotes('');
    setShowVerifyModal(true);
  };

  const filteredUsers = users.filter(u => {
    if (searchTerm && !u.fullName.toLowerCase().includes(searchTerm.toLowerCase()) && 
        !u.email.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }
    return true;
  });

  const sortedUsers = [...filteredUsers].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  if (loading) {
    return (
      <div style={{ display: 'flex' }}>
        <AdminSidebar />
        <div style={{ flex: 1, padding: '2rem', textAlign: 'center' }}>Loading users...</div>
      </div>
    );
  }

  // Styles
  const pageStyle = { display: 'flex', minHeight: '100vh' };
  const contentStyle = { flex: 1, padding: '2rem', background: '#FFFBF7', overflowX: 'auto' };
  const tableContainerStyle = { background: 'white', borderRadius: '32px', border: '1px solid #FFE2D4', overflowX: 'auto', width: '100%' };
  const tableStyle = { width: '100%', borderCollapse: 'collapse', minWidth: '1000px' };
  const thStyle = { padding: '1rem', textAlign: 'left', borderBottom: '1px solid #FFE2D4', background: '#FFF7F0', color: '#936E5C', fontWeight: '600' };
  const tdStyle = { padding: '1rem', textAlign: 'left', borderBottom: '1px solid #FFE2D4' };
  const verifyBadgeStyle = { background: '#FFF2EB', color: '#E57A5C', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' };
  const approvedBadgeStyle = { background: '#E0F2E9', color: '#4B7B6E', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' };
  const activeStatusStyle = { background: '#E0F2E9', color: '#4B7B6E', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-block' };
  const suspendedStatusStyle = { background: '#FFE5D9', color: '#C27D62', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-block' };
  const verifyBtnStyle = { background: '#FEF0EA', border: 'none', padding: '6px 14px', borderRadius: '60px', cursor: 'pointer', color: '#6B9C8F', fontSize: '12px', marginRight: '8px' };
  const suspendBtnStyle = { background: '#FEF0EA', border: 'none', padding: '6px 14px', borderRadius: '60px', cursor: 'pointer', color: '#E57A5C', fontSize: '12px' };

  return (
    <div style={pageStyle}>
      <AdminSidebar />
      <div style={contentStyle}>
        <h1 style={{ fontSize: '2rem', background: 'linear-gradient(135deg, #AD8878, #6EA094)', WebkitBackgroundClip: 'text', color: 'transparent', marginBottom: '1rem' }}>
          <i className="fas fa-users"></i> MANAGE USERS
        </h1>

        <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
          <div style={{ padding: '0.5rem 1.2rem', background: 'white', borderRadius: '60px', border: '1px solid #FFE2D4' }}>
            <i className="fas fa-users"></i> Total: {users.length}
          </div>
          <div style={{ padding: '0.5rem 1.2rem', background: '#FFF2EB', borderRadius: '60px', border: '1px solid #FFD4C4' }}>
            <i className="fas fa-clock"></i> Pending: {users.filter(u => u.verificationStatus === 'pending').length}
          </div>
          <div style={{ padding: '0.5rem 1.2rem', background: '#E0F2E9', borderRadius: '60px', border: '1px solid #C5E0D5' }}>
            <i className="fas fa-check-circle"></i> Verified: {users.filter(u => u.verificationStatus === 'approved').length}
          </div>
        </div>

        <input
          type="text"
          placeholder="Search by name or email..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', maxWidth: '400px', padding: '12px 20px', borderRadius: '60px', border: '1px solid #FFDDD0', background: 'white', marginBottom: '2rem' }}
        />

        <div style={tableContainerStyle}>
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thStyle}>User</th>
                <th style={thStyle}>Contact</th>
                <th style={thStyle}>Registered</th>
                <th style={thStyle}>Verification</th>
                <th style={thStyle}>Status</th>
                <th style={thStyle}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {sortedUsers.map(u => (
                <tr key={u._id} style={{ borderBottom: '1px solid #FFE2D4', background: u.verificationStatus === 'pending' ? 'rgba(255, 242, 235, 0.3)' : 'white' }}>
                  <td style={tdStyle}>
                    <div>
                      <div style={{ fontWeight: '600', color: '#5E4B3F' }}>{u.fullName}</div>
                      <div style={{ fontSize: '0.75rem', color: '#A98978' }}>{u.email}</div>
                    </div>
                  </td>
                  <td style={tdStyle}>{u.contact}</td>
                  <td style={tdStyle}>{new Date(u.createdAt).toLocaleDateString()}</td>
                  <td style={tdStyle}>
                    {u.verificationStatus === 'approved' ? (
                      <span style={approvedBadgeStyle}><i className="fas fa-check-circle"></i> VERIFIED</span>
                    ) : u.verificationStatus === 'rejected' ? (
                      <span style={{ background: '#FFE5D9', color: '#C27D62', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                        <i className="fas fa-times-circle"></i> REJECTED
                      </span>
                    ) : (
                      <span style={verifyBadgeStyle}><i className="fas fa-clock"></i> PENDING</span>
                    )}
                  </td>
                  <td style={tdStyle}>
                    <span style={u.isSuspended ? suspendedStatusStyle : activeStatusStyle}>
                      {u.isSuspended ? 'SUSPENDED' : 'ACTIVE'}
                    </span>
                  </td>
                  <td style={tdStyle}>
                    {u.verificationStatus === 'pending' && (
                      <button style={verifyBtnStyle} onClick={() => openVerifyModal(u)}>
                        <i className="fas fa-id-card"></i> Verify
                      </button>
                    )}
                    <button style={suspendBtnStyle} onClick={() => handleSuspend(u._id, u.isSuspended)}>
                      <i className={`fas ${u.isSuspended ? 'fa-user-check' : 'fa-ban'}`}></i>
                      {u.isSuspended ? ' Unsuspend' : ' Suspend'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Verify Modal */}
      {showVerifyModal && selectedUser && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(5px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }} onClick={() => setShowVerifyModal(false)}>
          <div style={{ background: 'white', maxWidth: '550px', width: '90%', borderRadius: '48px', padding: '2rem', maxHeight: '85vh', overflowY: 'auto' }} onClick={(e) => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
              <h2 style={{ color: '#AC7E68', margin: 0 }}><i className="fas fa-id-card"></i> Verify User</h2>
              <button onClick={() => setShowVerifyModal(false)} style={{ background: 'none', border: 'none', fontSize: '1.8rem', cursor: 'pointer', color: '#B28678' }}>×</button>
            </div>

            <div style={{ marginBottom: '1.5rem' }}>
              <div style={{ margin: '0.8rem 0', padding: '0.8rem 0', borderBottom: '1px solid #FFE2D4' }}>
                <strong style={{ width: '100px', display: 'inline-block' }}>Name:</strong> {selectedUser.fullName}
              </div>
              <div style={{ margin: '0.8rem 0', padding: '0.8rem 0', borderBottom: '1px solid #FFE2D4' }}>
                <strong style={{ width: '100px', display: 'inline-block' }}>Email:</strong> {selectedUser.email}
              </div>
              <div style={{ margin: '0.8rem 0', padding: '0.8rem 0', borderBottom: '1px solid #FFE2D4' }}>
                <strong style={{ width: '100px', display: 'inline-block' }}>Contact:</strong> {selectedUser.contact}
              </div>
              <div style={{ margin: '0.8rem 0', padding: '0.8rem 0' }}>
                <strong style={{ width: '100px', display: 'inline-block' }}>ID Uploaded:</strong> {selectedUser.idFileName || 'Yes'}
              </div>
            </div>

            <div style={{ margin: '1rem 0' }}>
              <label style={{ display: 'block', fontWeight: '600', color: '#936E5C', marginBottom: '0.5rem' }}>Admin Notes</label>
              <textarea
                rows="3"
                value={adminNotes}
                onChange={(e) => setAdminNotes(e.target.value)}
                placeholder="Add notes about this verification..."
                style={{ width: '100%', padding: '12px', borderRadius: '20px', border: '1px solid #FFDDD0', resize: 'vertical', fontFamily: 'inherit' }}
              />
            </div>

            <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
              <button onClick={() => handleVerify(true)} style={{ flex: 1, background: '#E0F2E9', border: 'none', padding: '12px', borderRadius: '60px', fontWeight: '600', color: '#4B7B6E', cursor: 'pointer' }}>
                <i className="fas fa-check-circle"></i> Approve User
              </button>
              <button onClick={() => handleVerify(false)} style={{ flex: 1, background: '#FFE5D9', border: 'none', padding: '12px', borderRadius: '60px', fontWeight: '600', color: '#C27D62', cursor: 'pointer' }}>
                <i className="fas fa-times-circle"></i> Reject User
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminUsersPage;
